import React, { useEffect, useRef } from "react";
import ScrollHorizontal from "react-scroll-horizontal";

import MobileScrollUp from "../../../shared/mobile/MobileScrollUp";
import { data } from "../data-proj";
import MobilePortoCard from "./MobilePortoCard";

const MobileProjectsContent = () => {
  const ref = useRef(null);

  useEffect(() => {
    const wrapper = ref.current;
    if (!wrapper) return;

    const scrollEl = wrapper.querySelector("div");
    if (!scrollEl) return;

    let startX = 0;

    const onTouchStart = (e) => {
      if (!e.touches?.length) return;
      startX = e.touches[0].clientX;
    };

    const onTouchMove = (e) => {
      if (!e.touches?.length) return;

      const nextX = e.touches[0].clientX;
      const dx = startX - nextX;
      startX = nextX;

      if (Math.abs(dx) < 2) return;

      e.preventDefault();

      scrollEl.dispatchEvent(
        new WheelEvent("wheel", {
          deltaY: dx,
          bubbles: true,
          cancelable: true,
        })
      );
    };

    wrapper.addEventListener("touchstart", onTouchStart, { passive: true });
    wrapper.addEventListener("touchmove", onTouchMove, { passive: false });

    return () => {
      wrapper.removeEventListener("touchstart", onTouchStart);
      wrapper.removeEventListener("touchmove", onTouchMove);
    };
  }, []);

  return (
    <div
      style={{
        height: "calc(100dvh - var(--nav-height))",
        width: "100%",
        position: "relative",
        borderRadius: "20px",
        overflow: "hidden",
      }}
    >
      <div ref={ref} className="exp-scroll-wrapper">
        <ScrollHorizontal>
          {data.map((element, index) => {
            const margin =
              index % 2 === 0
                ? index === 0
                  ? "50px 35px"
                  : "50px 45px"
                : "100px 45px";

            return (
              <div key={element.header} style={{ margin }}>
                <MobilePortoCard header={element.header} text={element.text} />
              </div>
            );
          })}
        </ScrollHorizontal>
      </div>

      <div
        style={{
          position: "absolute",
          bottom: "calc(var(--nav-height) + -10px)",
          left: 0,
          right: 0,
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
        }}
      >
        <MobileScrollUp />
      </div>
    </div>
  );
};

export default React.memo(MobileProjectsContent);
